#include <iostream>

int main() {
    int modo = 0;
    char nuevo = 'A';

    if (!(std::cin >> modo >> nuevo)) {
        return 1;
    }
    char datos[6]{'s', 'o', 'l', '\0', 'X', 'Y'};
    if (modo == 1) {
        datos[3] = 'a';
        datos[4] = 'r';
        datos[5] = '\0';
    } else if (modo == 2) {
        datos[3] = 'A';
    } else if (modo == 3) {
        datos[0] = '\0';
    } else if (modo == 4) {
        datos[1] = '\0';
    } else if (modo != 0) {
        return 1;
    }
    const int capacidad =
        static_cast<int>(sizeof datos / sizeof datos[0]);
    int longitud = 0;
    while (longitud < capacidad && datos[longitud] != '\0') {
        ++longitud;
    }
    const bool terminada = longitud < capacidad;

    bool aceptado = false;
    if (terminada) {
        // Comprueba el espacio antes de escribir.
        // Anade nuevo y el terminador siguiente solo al aceptar.

    }

    int longitudActual = 0;
    while (longitudActual < capacidad && datos[longitudActual] != '\0') {
        ++longitudActual;
    }
    std::cout << "Aceptado=" << aceptado << '\n';
    std::cout << "Texto=";
    if (longitudActual < capacidad) {
        std::cout << datos;
    } else {
        std::cout << "(sin terminador)";
    }
    std::cout << '\n' << "Datos=";
    for (int i = 0; i < capacidad; ++i) {
        if (i != 0) {
            std::cout << ' ';
        }
        if (datos[i] == '\0') {
            std::cout << "NUL";
        } else {
            std::cout << datos[i];
        }
    }
    std::cout << '\n' << "Capacidad=" << capacidad << '\n';

    return 0;
}

